import random

def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_prev, opp_prev = history[-1]

    def opp_counts():
        c = 0
        d = 0
        for _, o in history:
            if o == 'C':
                c += 1
            else:
                d += 1
        return c, d

    def transitions():
        cc = cd = dc = dd = 0
        for i in range(1, n):
            p_my, p_opp = history[i - 1]
            _, cur_opp = history[i]
            if p_opp == 'C' and cur_opp == 'C':
                cc += 1
            elif p_opp == 'C' and cur_opp == 'D':
                cd += 1
            elif p_opp == 'D' and cur_opp == 'C':
                dc += 1
            else:
                dd += 1
        return cc, cd, dc, dd

    opp_c, opp_d = opp_counts()

    # Strong retaliation while still probing for cooperation.
    if opp_prev == 'D':
        # If opponent defects very often, defect more.
        if opp_d >= n - opp_d + 2:
            return 'D'
        # Occasionally forgive if recent signals suggest they may return to C.
        if n >= 4:
            recent = history[-4:]
            opp_recent_d = sum(1 for _, o in recent if o == 'D')
            if opp_recent_d <= 1 and rng.random() < 0.22:
                return 'C'
        return 'D'

    # Opponent just cooperated.
    if n >= 6:
        cc, cd, dc, dd = transitions()
        # Exploit someone who alternates after our cooperation, e.g. CD/CD.
        if cd >= 2 and cc <= 1 and rng.random() < 0.55:
            return 'D'
        # If they mostly cooperate, cooperate to preserve high payoff.
        if opp_c >= opp_d:
            return 'C'
        # If they often punish after our C, be defensive.
        if dc >= 2 and opp_d >= 2:
            return 'D'

    # Early: cooperate, but occasionally test.
    if n < 10:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Late game: if clearly behind in mutual cooperation, push defection.
    if n >= 85:
        if opp_c >= opp_d:
            return 'C'
        return 'D'

    # Moderate Pavlov-like response: reward opponent's cooperation.
    if my_prev == 'D' and opp_prev == 'C':
        return 'C'
    return 'C'

